package com.cricketsim.logic

import java.util.Locale
import kotlin.math.roundToInt

/**
 * My Player, part fifteen: money. A player is paid in match fees (club, state and national matches; franchise league matches are covered by the league contract),
 * in a national central contract once he is an international, in a league contract when he signs for a franchise, and in prizes when his team wins a competition.
 * Match fees are paid as he plays ([matchFee]); the contracts and the prizes when the season is settled ([settle]). The figures are in dollars, invented for the game.
 *
 * A league contract ([contractFor]) is the league's base (IPL 400,000 ... Abu Dhabi T10 50,000) times 0.4 plus his main rating over 100, 10% more if the franchise keeps him from the
 * year before ([CareerProfile.lastLeagueTeamId]), 25% more for an international. Dials: [matchFee], [BASE], the central contract in [centralContract].
 */
object CareerFinance {

    class Payout(val career: CareerProfile, val text: String)

    fun money(amount: Long): String = "\$" + String.format(Locale.US, "%,d", amount)

    /** What he is paid for a match: Test 4,000, one-day 2,500, T20 international 1,500 (also the T20 World Cup and so on), state 120, club 25; none for a franchise league match. */
    fun matchFee(career: CareerProfile, format: String, league: Boolean): Int = when {
        league -> 0
        format == "test" -> 4000
        format == "odi" -> 2500
        format == "t20" -> 1500
        career.isState -> 120
        else -> 25
    }

    private val BASE = mapOf(
        "ipl" to 400_000, "bbl" to 150_000, "sa20" to 120_000, "cpl" to 100_000,
        "mlc" to 100_000, "ilt20" to 90_000, "lpl" to 60_000, "adt10" to 50_000
    )

    fun contractFor(career: CareerProfile, leagueId: String, retained: Boolean): Int {
        val main = when (CareerSeason.roleOf(career.role)) {
            PlayerRole.BOWLER -> career.bowling.toDouble()
            PlayerRole.ALL_ROUNDER -> (career.batting + career.bowling) / 2.0
            else -> career.batting.toDouble()
        }
        val raw = (BASE[leagueId] ?: 50_000) * (0.4 + main / 100.0) * (if (retained) 1.1 else 1.0) * (if (career.isInternational) 1.25 else 1.0)
        return (raw / 1000.0).roundToInt() * 1000
    }

    fun contract(career: CareerProfile, offer: LeagueOffer): Int = contractFor(career, offer.leagueId, career.lastLeagueTeamId == offer.teamId)

    /** The national central contract for the season: 60,000, 20,000 more for a vice-captain, 40,000 more for a captain. */
    fun centralContract(career: CareerProfile): Long =
        if (!career.isInternational) 0L else 60_000L + when (career.nationalRole) {
            "Captain" -> 40_000L
            "Vice-captain" -> 20_000L
            else -> 0L
        }

    /** At the end of a season: the contracts and the prizes are paid. */
    fun settle(career: CareerProfile, states: List<TournamentState>): Payout {
        var contracts = centralContract(career)
        if (career.leagueContract > 0 && career.leagueDecidedSeason == career.season) contracts += career.leagueContract.toLong()
        var prizes = 0L
        for (s in states) {
            if (!CareerSeason.isComplete(s)) continue
            val champion = CareerSeason.champion(s) ?: continue
            if (champion.id != s.userTeamId) continue
            prizes += when {
                CareerInternational.isTournament(s) || CareerLeagues.isLeague(s) -> 20_000L
                CareerInternational.isSeries(s) -> 5_000L
                else -> 500L
            }
        }
        val fees = career.seasonEarnings
        val total = fees + contracts + prizes
        val updated = career.copy(money = career.money + contracts + prizes, seasonEarnings = total)
        val text = if (total <= 0L) "" else " This season you earned ${money(total)}: ${money(fees)} in match fees, ${money(contracts)} in contracts and ${money(prizes)} in prizes."
        return Payout(updated, text)
    }

    /** The money part of the Career tab. */
    fun lines(career: CareerProfile): List<String> {
        val out = ArrayList<String>()
        out.add("Career earnings: ${money(career.money)}.")
        if (!career.retired) {
            out.add("This season so far, in match fees: ${money(career.seasonEarnings)}.")
            if (career.leagueContract > 0 && career.leagueDecidedSeason == career.season) {
                out.add("Your league contract this season is worth ${money(career.leagueContract.toLong())}, paid when the season ends.")
            }
            if (career.isInternational) out.add("Your national central contract pays ${money(centralContract(career))} when the season ends.")
        }
        return out
    }
}

/**
 * My Player, part fifteen: what the papers say. When a season is settled each finished competition may earn a line (the star of the competition, a hundred,
 * a five-wicket haul, 200 runs, eight wickets, or a poor run over three or more matches). The last fifteen lines are kept for the Career tab.
 */
object CareerMedia {

    private fun starOf(state: TournamentState, pid: String): Boolean {
        val best = state.playerStats.values.maxWithOrNull(compareBy<PlayerStats>({ it.impact }, { it.runs + it.wickets * 20 })) ?: return false
        return best.playerId == pid && best.impact > 0.0
    }

    fun lines(career: CareerProfile, states: List<TournamentState>): List<String> {
        val out = ArrayList<String>()
        for (s in states) {
            if (!CareerSeason.isComplete(s)) continue
            val pid = CareerSeason.playerIdIn(s, career) ?: continue
            val st = s.playerStats[pid] ?: continue
            if (st.matches == 0) continue
            val tag = "Season ${career.season}, ${CareerSeason.competitionOf(s).label}: "
            val averageImpact = st.impact / st.matches
            val line = when {
                starOf(s, pid) -> "the papers name you the star of the competition."
                st.hundreds > 0 -> "a hundred makes the headlines: your best was ${st.highScore}."
                st.fiveWickets > 0 -> "a five-wicket haul has the pundits talking."
                st.runs >= 200 -> "commentators praise your ${st.runs} runs."
                st.wickets >= 8 -> "you are the talk of the dressing room with ${st.wickets} wickets."
                st.matches >= 3 && averageImpact < 8.0 -> "the press ask whether you are good enough: little to show in ${st.matches} matches."
                else -> null
            }
            if (line != null) out.add(tag + line)
        }
        return out.take(4)
    }
}

package com.cricketsim.ui.career

import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.height
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.semantics.heading
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.unit.dp
import com.cricketsim.logic.CareerFinance
import com.cricketsim.logic.CareerHealth
import com.cricketsim.logic.CareerInternational
import com.cricketsim.logic.CareerProfile
import com.cricketsim.logic.CareerRecords
import com.cricketsim.logic.CareerSeason
import com.cricketsim.logic.TournamentState
import com.cricketsim.ui.custom.OptionButton
import com.cricketsim.ui.custom.PageHeading

/**
 * The career's Career tab (My Player, parts eleven to fifteen): this season's objectives, the training focus, fitness, the rankings, the career record,
 * the honours and retirement; for a retired player the career summary comes first and the rest of the playing parts are left out.
 * Every part has a heading, then plain sentences, so a screen reader can jump from heading to heading.
 */
@Composable
internal fun CareerRecordTab(
    career: CareerProfile,
    seasons: List<TournamentState>?,
    rankLines: List<String>,
    onFocus: (String?) -> Unit,
    onSpecialism: (String?) -> Unit,
    onRetire: () -> Unit
) {
    PageHeading("Career")
    Spacer(modifier = Modifier.height(8.dp))

    if (career.retired) {
        SectionHeading("Career summary")
        CareerHealth.summaryLines(career).forEach { BodyLine(it) }
    } else {
        SectionHeading("Season objectives")
        val objectives = if (seasons == null) emptyList() else CareerRecords.objectiveLines(career, seasons)
        if (objectives.isEmpty()) {
            BodyLine("Objectives appear when the season has loaded.")
        } else {
            objectives.forEach { BodyLine(it) }
            BodyLine("Every objective you reach gives +1 to the rating it is about when the season ends.")
        }

        SectionHeading("Fitness")
        BodyLine(CareerHealth.statusLine(career) ?: "Fitness: you are fit and well.")
        BodyLine("Injuries are more likely in Test cricket, for bowlers, after thirty and when you are tired. From 33 your ratings slowly fall with age.")

        SectionHeading("Training focus")
        BodyLine("The skill you work on grows faster after matches, the others a little slower. Now: ${career.trainingFocus ?: "balanced"}.")
        listOf<Pair<String?, String>>(
            null to "Balanced",
            "Batting" to "Batting",
            "Bowling" to "Bowling",
            "Fielding" to "Fielding"
        ).forEach { (value, label) ->
            val chosen = career.trainingFocus == value
            Spacer(modifier = Modifier.height(6.dp))
            OptionButton(
                if (chosen) "$label (chosen)" else label,
                if (value == null) "All three skills grow at the normal rate." else "$label grows faster, the other skills slower.",
                !chosen, false
            ) { onFocus(value) }
        }
    }

    if (!career.retired && career.atOrAboveState) {
        SectionHeading("Format specialism")
        BodyLine(
            "A specialist is preferred by the selectors in his format (a place in his favour) and less in the other (a place against). " +
                "A white-ball specialist also gets more franchise league offers; a Test specialist gets fewer. Now: ${career.specialism?.let { if (it == "Test") "Test specialist" else "white-ball specialist" } ?: "all formats"}."
        )
        listOf<Pair<String?, String>>(
            null to "All formats",
            "Test" to "Test specialist",
            "White-ball" to "White-ball specialist"
        ).forEach { (value, label) ->
            val chosen = career.specialism == value
            Spacer(modifier = Modifier.height(6.dp))
            OptionButton(
                if (chosen) "$label (chosen)" else label,
                when (value) {
                    "Test" -> "Test series are yours; one-day and T20 matches and leagues are harder to get into."
                    "White-ball" -> "One-day and T20 matches and leagues are yours; Test series are harder to get into."
                    else -> "No preference: every format is judged the same."
                },
                !chosen, false
            ) { onSpecialism(value) }
        }
    }
    if (!career.retired && career.isInternational) {
        SectionHeading("National captaincy")
        BodyLine(CareerInternational.captaincyLine(career))
    }

    SectionHeading("Rankings")
    if (rankLines.isEmpty()) BodyLine("Working out your rankings.") else rankLines.forEach { BodyLine(it) }

    SectionHeading("Career record")
    val record = CareerRecords.recordLines(career)
    if (record.isEmpty()) BodyLine("No matches yet. Your record grows with every match you play.") else record.forEach { BodyLine(it) }

    SectionHeading("Honours")
    val honours = career.honours.orEmpty()
    if (honours.isEmpty()) BodyLine("None yet. Win a competition or be Player of the Series.") else honours.reversed().forEach { BodyLine(it) }

    SectionHeading("Earnings")
    CareerFinance.lines(career).forEach { BodyLine(it) }

    SectionHeading("In the news")
    val news = career.media.orEmpty()
    if (news.isEmpty()) BodyLine("Nothing yet. The papers write about you when a competition ends.") else news.reversed().forEach { BodyLine(it) }

    if (!career.retired) {
        SectionHeading("Retirement")
        BodyLine("You are ${career.age}. Players usually retire between 36 and 42, earlier if their ratings fall.")
        var confirm by remember { mutableStateOf(false) }
        val seasonDone = seasons != null && seasons.isNotEmpty() && seasons.all { CareerSeason.isComplete(it) }
        Spacer(modifier = Modifier.height(6.dp))
        if (!confirm) {
            OptionButton(
                "Retire from cricket",
                if (seasonDone) "End your career and see your career summary." else "You can retire when the season is finished.",
                seasonDone, false
            ) { confirm = true }
        } else {
            BodyLine("Are you sure? Retiring ends your career for good.")
            OptionButton("Yes, retire now", "Your career ends and the summary appears here.", true, true) {
                confirm = false
                onRetire()
            }
            Spacer(modifier = Modifier.height(6.dp))
            OptionButton("No, keep playing", "Go back to your career.", true, false) { confirm = false }
        }
    }
}

@Composable
private fun SectionHeading(text: String) {
    Spacer(modifier = Modifier.height(16.dp))
    Text(text, style = MaterialTheme.typography.titleMedium, modifier = Modifier.semantics { heading() })
    Spacer(modifier = Modifier.height(4.dp))
}

@Composable
private fun BodyLine(text: String) {
    Text(text, style = MaterialTheme.typography.bodyMedium)
    Spacer(modifier = Modifier.height(4.dp))
}
